// ---------- 12. Kết quả ----------
function resultBody(o = {}) {
  const stat = (t, a, b, fmt = (x) => x) => { const tot = a + b || 1; return `<div style="display: grid; grid-template-columns: 44px 1fr 44px; gap: 12px; align-items: center"><span class="display num" style="font-size: 22px">${fmt(a)}</span><div style="display: flex; flex-direction: column; gap: 4px"><span class="label" style="text-align: center">${t}</span><div style="display: flex; gap: 3px; height: 6px"><span style="flex: ${a / tot}; background: var(--c-team-home); border-radius: 3px 0 0 3px"></span><span style="flex: ${b / tot}; background: var(--c-team-away); border-radius: 0 3px 3px 0"></span></div></div><span class="display num" style="font-size: 22px; text-align: right">${fmt(b)}</span></div>`; };
  const res = o.res || ['THẮNG', 'var(--c-accent)'];
  return `<div style="position: absolute; inset: 0" class="night-bg"></div><div style="position: relative; height: 100%; padding: 40px 64px; box-sizing: border-box; display: grid; grid-template-columns: minmax(0, 1fr) 400px; gap: 40px">
<div style="display: flex; flex-direction: column; gap: 20px; min-width: 0">
<span class="label">Kết thúc · vs Máy mức Khó · ${o.extra || '2 hiệp'}</span>
<div style="display: flex; align-items: center; gap: 28px"><span class="display" style="font-size: 28px; display: flex; gap: 10px; align-items: center"><span style="width: 12px; height: 36px; background: var(--c-team-home)"></span>NHÀ</span><span class="display num" style="font-size: 132px; line-height: .85">${o.score || '3 – 1'}</span><span class="display" style="font-size: 28px; display: flex; gap: 10px; align-items: center">KHÁCH<span style="width: 12px; height: 36px; background: var(--c-team-away)"></span></span></div>
<span class="display" style="font-size: 56px; line-height: 1; color: ${res[1]}; text-transform: uppercase">${res[0]}</span>
<section class="panel" style="display: flex; flex-direction: column; gap: 12px; padding: 18px 24px">${stat('Sút', 9, 4)}${stat('Sút trúng đích', 5, 2)}${stat('Kiểm soát bóng', 58, 42, (x) => x + '%')}${stat('Thẻ vàng', 1, 2)}${stat('Thẻ đỏ', 0, 1)}</section>
<p class="muted" style="margin: 0; font-size: 14px">Ghi bàn: V. Vuketić 12', 67' · ${by('gold', 'MF', 0).name} 44' — ${by('silver', 'FW', 1).name} 51'</p>
</div>
<div style="display: flex; flex-direction: column; gap: 16px">
<section class="panel--notch"><div class="panel__in" style="display: flex; flex-direction: column; gap: 6px; align-items: flex-start">${o.coinBlock || `<span class="label">Thưởng trận</span>${coin('+120', 'coin--xl')}<span class="muted" style="font-size: 14px">Thắng mức Khó · trận có thưởng 4/15 · ví: 1.360 xu</span>`}</div></section>
<section class="panel" style="padding: 16px 20px"><h3 class="panel__title" style="margin-bottom: 0">Nhiệm vụ vừa tăng</h3>${missions()}</section>
<div style="margin-top: auto; display: flex; gap: 12px">${o.actions || '<a class="btn btn--primary btn--lg" href="PreMatch.dc.html" style="flex: 1">Đá tiếp</a><a class="btn btn--secondary btn--lg" href="Home.dc.html" style="flex: 1">Về trang chủ</a>'}</div>
</div></div>`;
}
B['Result.dc.html'] = { title: 'Kết quả trận', w: 1280, h: 720, interactive: true, body: `${resultBody()}<div class="motion-note" style="position: absolute; right: 64px; top: 20px; width: 400px; background: rgb(10 19 16 / .9)"><b>Nhận xu</b> · "+120" đếm từ 0 trong 400ms (tabular, không nhảy) → 6 đồng xu bay về ví ở thanh trên (240ms, stagger 80ms) → số ví đếm lên. Thanh nhiệm vụ chạy tới giá trị mới 400ms.</div>` };
{
  const mini = (title, inner) => stateCell(title, inner);
  B['Result-States.dc.html'] = statesBoard('Kết quả — luân lưu, không thưởng, lỗi gửi', 4, [
    mini('Thắng luân lưu', `<span class="display num" style="font-size: 56px; line-height: .9">2 – 2</span><span class="muted" style="font-size: 14px">Luân lưu <b class="num" style="color: var(--c-text)">4 – 3</b></span><span class="display" style="font-size: 32px; color: var(--c-accent)">THẮNG LUÂN LƯU</span>${coin('+90', 'coin--lg')}<span class="muted" style="font-size: 12px">= thưởng hoà 60 + 50% chênh lệch (Khó)</span>`),
    mini('Thua luân lưu', `<span class="display num" style="font-size: 56px; line-height: .9">1 – 1</span><span class="muted" style="font-size: 14px">Luân lưu <b class="num" style="color: var(--c-text)">2 – 4</b></span><span class="display" style="font-size: 32px; color: var(--c-team-away)">THUA LUÂN LƯU</span>${coin('+30', 'coin--lg')}<span class="muted" style="font-size: 12px">Giả định: tính như thua (30 xu, Khó) — PRD chưa chốt</span>`),
    mini('Không có thưởng', `<span class="display num" style="font-size: 56px; line-height: .9">3 – 0</span><span class="display" style="font-size: 32px; color: var(--c-accent)">THẮNG</span><div class="banner">${ICON.warn}<span><b>Trận luyện tập</b> — đã đủ 15 trận có thưởng hôm nay. Nhiệm vụ vẫn tính.</span></div>${coin('+0', 'coin--lg').replace('class="coin coin--lg"', 'class="coin coin--lg" style="color: var(--c-text-muted)"')}`),
    mini('Lỗi gửi kết quả', `<span class="display num" style="font-size: 56px; line-height: .9">2 – 1</span><span class="display" style="font-size: 32px; color: var(--c-accent)">THẮNG</span><div class="banner banner--danger">${ICON.warn}<span><b>Chưa gửi được kết quả.</b> Thưởng sẽ được cộng khi máy chủ xác nhận. Kết quả đã lưu trên máy.</span></div><button class="btn btn--primary">Gửi lại</button><button class="btn btn--primary is-loading" aria-busy="true"><span class="btn__label">Gửi lại</span></button><span class="muted" style="font-size: 12px">Server kiểm tra lại trận; client không tự cộng xu.</span>`),
  ]);
}

